#include <bits/stdc++.h>
using namespace std;

using ll = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int t;
    cin >> t;

    while (t--) {
        ll n, A, B, x, y, z;
        cin >> n >> A >> B >> x >> y >> z;

        priority_queue<ll> q;
        for (ll i = 0; i < n; ++i) {
            ll p;
            cin >> p;
            q.push(p);
        }

        ll bb = z - B;
        if (bb <= 0) {
            cout << "RIP\n";
            continue;
        }

        ll w = (bb <= y) ? 0 : (bb - 1) / y;
        ll aa = z - A;
        __int128 cumulative = static_cast<__int128>(x) * w;

        if (static_cast<__int128>(aa) < cumulative) {
            cout << "0\n";
            continue;
        }

        aa -= static_cast<ll>(cumulative);

        ll count = 0;
        while (!q.empty() && aa > 0) {
            ll value = q.top();
            q.pop();

            aa -= value;
            ++count;

            if (value / 2 != 0)
                q.push(value / 2);
        }

        if (aa <= 0)
            cout << count << '\n';
        else
            cout << "RIP\n";
    }

    return 0;
}

