        ll bb = z - B;
        ll w = 0;

        if (bb > 0) {
            if (bb <= y) {
                w = 0;
            } else if (bb % y == 0) {
                w = bb / y - 1;
            } else {
                w = bb / y;
            }
        }

        ll aa = z - A;
        __int128 cumulative = static_cast<__int128>(x) * w;
        bool simulate = bb > 0 && static_cast<__int128>(aa) >= cumulative;

        vector<ll> values;
        if (simulate)
            values.reserve(static_cast<size_t>(n));

        for (ll i = 0; i < n; ++i) {
            ll p;
            cin >> p;
            if (simulate)
