        }

        if (bb <= 0) {
            cout << "RIP\n";
            continue;
        }

        if (!simulate) {
            cout << "0\n";
            continue;
        }

        aa -= static_cast<ll>(cumulative);

        priority_queue<ll, vector<ll>, less<ll>> q(
            less<ll>(), move(values)
        );

        ll count = 0;

        while (!q.empty()) {
            ll current = q.top();
            q.pop();

            aa -= current;
            ++count;

            if (current / 2 != 0)
                q.push(current / 2);

            if (aa <= 0)
                break;
        }

        if (aa <= 0)
            cout << count << '\n';
        else
            cout << "RIP\n";
    }

    return 0;
