#include <bits/stdc++.h>
using namespace std;

using ll = long long;
using i128 = __int128_t;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int t;
    cin >> t;

    while (t--) {
        int n;
        ll A, B, x, y, z;
        cin >> n >> A >> B >> x >> y >> z;

        ll bb = z - B;
        ll w = 0;

        if (bb > 0) {
            if (bb <= y) {
                w = 0;
            } else {
                w = (bb - 1) / y;
            }
        }

        ll aa = z - A;
        i128 cumulative = static_cast<i128>(x) * w;
        bool needHeap = bb > 0 && static_cast<i128>(aa) >= cumulative;

        vector<int> heap;
        if (needHeap) heap.reserve(n);

        for (int i = 0; i < n; ++i) {
            int p;
            cin >> p;
            if (needHeap) heap.push_back(p);
        }

        if (bb <= 0) {
            cout << "RIP\n";
            continue;
        }

        if (!needHeap) {
            cout << "0\n";
            continue;
        }

        aa -= static_cast<ll>(cumulative);
        make_heap(heap.begin(), heap.end());

        ll count = 0;

        while (!heap.empty() && aa > 0) {
            pop_heap(heap.begin(), heap.end());
            int top = heap.back();
            heap.pop_back();

            aa -= top;
            ++count;

            if (top / 2 != 0) {
                heap.push_back(top / 2);
                push_heap(heap.begin(), heap.end());
            }
        }

        if (aa <= 0) {
            cout << count << '\n';
        } else {
            cout << "RIP\n";
        }
    }

    return 0;
}

