        for (int& value : values) {
            cin >> value;
        }

        priority_queue<int, vector<int>, less<int>> q(
            less<int>(), move(values)
        );

        long long bb = z - B;
        if (bb <= 0) {
            cout << "RIP\n";
            continue;
        }

        long long w = (bb <= y) ? 0 : (bb - 1) / y;
        __int128 remaining = static_cast<__int128>(z) - A;
        __int128 accumulated = static_cast<__int128>(x) * w;

        if (remaining < accumulated) {
            cout << "0\n";
            continue;
        }

        remaining -= accumulated;

        if (remaining <= 0) {
            cout << "0\n";
            continue;
        }

        long long count = 0;

        while (!q.empty() && remaining > 0) {
            int value = q.top();
            q.pop();

            remaining -= value;
            ++count;

            if (value / 2 != 0) {
                q.push(value / 2);
            }
        }

        if (remaining <= 0) {
            cout << count << '\n';
        } else {
            cout << "RIP\n";
        }
    }

